svg.script:
(async()=>{
'use strict';
const token=location.hash.slice(1),params=new URLSearchParams(location.search),origin=params.get('origin'),allowed=['https://www.instagram.com','https://instagram.com','https://m.instagram.com'];
if(!opener||!allowed.includes(origin)||!/^[A-Za-z0-9_-]{16,128}$/.test(token))return;
const send=m=>opener.postMessage({...m,token},origin);
function status(text){let el=document.getElementById('ri-status');if(!el){document.documentElement.setAttribute('width','100%');document.documentElement.setAttribute('height','100%');document.documentElement.setAttribute('viewBox','0 0 440 220');const bg=document.createElementNS('http://www.w3.org/2000/svg','rect');bg.setAttribute('width','440');bg.setAttribute('height','220');bg.setAttribute('fill','#171719');document.documentElement.appendChild(bg);el=document.createElementNS('http://www.w3.org/2000/svg','text');el.id='ri-status';el.setAttribute('x','16');el.setAttribute('y','75');el.setAttribute('fill','white');el.setAttribute('font-size','14');document.documentElement.appendChild(el)}el.textContent=String(text).slice(0,80)}
async function get(url,read){const c=new AbortController(),timer=setTimeout(()=>c.abort(),20000);try{const r=await fetch(url,{cache:'no-store',signal:c.signal});if(!r.ok)throw Error('HTTP '+r.status);return await read(r)}finally{clearTimeout(timer)}}
if(params.get('mode')!=='research'){
  try{status('RI 업데이트 확인 중');const j=await get('https://api.github.com/repos/sunsee83/open_lab/branches/main',r=>r.json()),sha=j?.commit?.sha;if(!/^[0-9a-f]{40}$/i.test(sha||''))throw Error('최신 commit 확인 실패');const code=await get(`https://raw.githubusercontent.com/sunsee83/open_lab/${sha}/bookmarklets/instagram/current.js`,r=>r.text());if(code.length<100||code.length>524288)throw Error('본체 코드 크기 오류');send({type:'RI_STABLE_CODE',target:'current.js',sha,code});status('본체 전달 완료')}catch(e){send({type:'RI_STABLE_ERROR',error:String(e.message||e)})}return;
}
status('기기 내 분석 준비 · 이 창을 열어두세요');
function loadScript(url){return new Promise((ok,no)=>{const s=document.createElementNS('http://www.w3.org/1999/xhtml','script');s.src=url;s.onload=ok;s.onerror=()=>no(Error('인식 엔진 다운로드 실패'));document.documentElement.appendChild(s)})}
async function speech(blob){
  status('음성 읽는 중');const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('이 브라우저는 오디오 분석을 지원하지 않습니다');const ctx=new Audio();let audio;try{audio=await ctx.decodeAudioData(await blob.arrayBuffer())}finally{await ctx.close()}if(!audio.duration||audio.duration>180)throw Error('음성 인식은 180초 이하 미디어를 지원합니다');
  const offline=new OfflineAudioContext(1,Math.ceil(audio.duration*16000),16000),input=offline.createBufferSource();input.buffer=audio;input.connect(offline.destination);input.start();const pcm=(await offline.startRendering()).getChannelData(0);
  status('음성 모델 다운로드 · 첫 실행은 시간이 걸립니다');const {pipeline,env}=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.8.1');env.allowLocalModels=false;env.backends.onnx.wasm.numThreads=1;
  const pipe=await pipeline('automatic-speech-recognition','Xenova/whisper-tiny',{device:'wasm',dtype:'q8'});try{status('이 기기에서 한국어 음성 인식 중');const result=await pipe(pcm,{language:'korean',task:'transcribe',chunk_length_s:30,stride_length_s:5,return_timestamps:true});return {text:result.text||'',chunks:result.chunks||[],source:'whisper-tiny-local',language:'ko'}}finally{await pipe.dispose()}
}
async function ocr(blob,mediaType){
  status('글자 인식 모델 다운로드');await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js');if(!window.Tesseract?.createWorker)throw Error('OCR 엔진을 찾을 수 없습니다');const worker=await Tesseract.createWorker('kor+eng',1,{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@6.0.0',logger:m=>{if(m.status==='recognizing text')status('이 기기에서 글자 인식 중')}});
  const canvas=document.createElementNS('http://www.w3.org/1999/xhtml','canvas'),frames=[];let video,url,bitmap;
  const wait=(event,start)=>new Promise((ok,no)=>{const end=error=>{clearTimeout(timer);video.removeEventListener(event,good);video.removeEventListener('error',bad);error?no(error):ok()},good=()=>end(),bad=()=>end(Error('영상 읽기 실패')),timer=setTimeout(()=>end(Error('영상 읽기 시간초과')),15000);video.addEventListener(event,good,{once:true});video.addEventListener('error',bad,{once:true});start()});
  async function recognize(frame,width,height,time){const scale=Math.min(1,1280/width);canvas.width=Math.round(width*scale);canvas.height=Math.round(height*scale);canvas.getContext('2d').drawImage(frame,0,0,canvas.width,canvas.height);const {data}=await worker.recognize(canvas,{}, {text:true,blocks:true});const lines=(data.blocks||[]).flatMap(b=>(b.paragraphs||[]).flatMap(p=>p.lines||[])).map(l=>({text:l.text||'',bbox:l.bbox,confidence:l.confidence}));frames.push({time,text:(data.text||'').trim(),width:canvas.width,height:canvas.height,lines})}
  try{let coverage;if(mediaType==='photo'){bitmap=await createImageBitmap(blob);await recognize(bitmap,bitmap.width,bitmap.height,null);coverage='이미지 1장'}else{url=URL.createObjectURL(blob);video=document.createElementNS('http://www.w3.org/1999/xhtml','video');video.muted=true;video.playsInline=true;video.preload='auto';await wait('loadeddata',()=>{video.src=url;video.load()});if(!Number.isFinite(video.duration)||video.duration<=0)throw Error('영상 길이 확인 실패');const count=Math.min(60,Math.ceil(video.duration/2));for(let i=0;i<count;i++){const t=i*2;if(video.currentTime!==t)await wait('seeked',()=>video.currentTime=t);status(`글자 인식 ${i+1}/${count} · ${t}초`);await recognize(video,video.videoWidth,video.videoHeight,t)}coverage=`2초 간격 ${count}프레임 · 0~${(count-1)*2}초 / 전체 ${video.duration.toFixed(1)}초`}
    return {text:[...new Set(frames.map(f=>f.text).filter(Boolean))].join('\n\n'),frames,coverage,source:'tesseract-local'};
  }finally{bitmap?.close();if(video){video.removeAttribute('src');video.load()}if(url)URL.revokeObjectURL(url);await worker.terminate()}
}
let used=false;
addEventListener('message',async e=>{const d=e.data;if(used||e.source!==opener||e.origin!==origin||!d||d.token!==token||d.type!=='RI_RESEARCH_INPUT'||!['stt','ocr'].includes(d.kind)||!(d.blob instanceof Blob)||d.blob.size>256*1024*1024||!['video','photo'].includes(d.mediaType))return;used=true;try{const result=d.kind==='stt'?await speech(d.blob):await ocr(d.blob,d.mediaType);send({type:'RI_RESEARCH_RESULT',kind:d.kind,result});status('인식 완료 · 원래 화면에서 결과를 확인하세요')}catch(e){send({type:'RI_RESEARCH_ERROR',error:String(e.message||e)});status('인식 실패: '+String(e.message||e))}});
send({type:'RI_RESEARCH_READY'});
})()
